class Printer {
    // OVERLOADING 1: print(String)
    public void print(String text) {
        System.out.println("Printing text: " + text);
    }

    // OVERLOADING 2: print(int) - Same class, different parameter
    public void print(int copies) {
        System.out.println("Printing " + copies + " blank pages");
    }

    // Method to be overridden
    public void printJobSummary() {
        System.out.println("Standard printer ready");
    }
}

class ColorLaserPrinter extends Printer {
    // OVERRIDING: Exact same signature, parent-child relationship
    @Override
    public void printJobSummary() {
        System.out.println("Color Laser Printer: High-resolution CMYK mode active");
    }

    // OVERLOADING ACROSS INHERITANCE: New parameter type
    public void print(String text, String colorMode) {
        System.out.println("Printing '" + text + "' in " + colorMode + " mode");
    }
}

public class OverloadOverrideDemo {
    public static void main(String[] args) {
        ColorLaserPrinter p = new ColorLaserPrinter();

        // Overloaded methods (resolved at compile-time)
        p.print("Document.pdf");
        p.print(5);
        p.print("Poster.png", "Pantone Color");

        // Overridden method (resolved at runtime)
        Printer baseRef = p;
        baseRef.printJobSummary(); // Runs ColorLaserPrinter version!
    }
}

