class TaxSystem {
    public int calculateTax(int income) {
        return (int)(income * 0.10);
    }

    // COMPILE ERROR if uncommented:
    // public double calculateTax(int income) { return income * 0.10; }
    // Error: Method already defined! Return type alone cannot overload a method!
}

class SpecializedTaxSystem extends TaxSystem {
    // COMPILE ERROR if uncommented:
    // @Override
    // public double calculateTax(int income) { return income * 0.15; }
    // Error: Cannot change primitive return type from int to double in an override!

    @Override
    public int calculateTax(int income) {
        return (int)(income * 0.15); // Valid override: exact same return type
    }
}

public class ReturnTypeTrapDemo {
    public static void main(String[] args) {
        TaxSystem sys = new SpecializedTaxSystem();
        System.out.println("Tax: $" + sys.calculateTax(50000));
    }
}

